#version 330
out vec4 fragColor;in vec2 fragCoord;uniform float elapsed;uniform vec2 resolution;void main(){float b=50.;vec3 c=vec3(236./255.,202./255.,128./255.);vec3 d=vec3(107./255.,178./255.,194./255.);vec2 e=(fragCoord-(resolution.xy/2.));float f=length(e);float g=100.;float h=g*(g/f);vec2 i=vec2(e.x*h/f+cos(elapsed*.9)*700.,e.y*h/f+sin(elapsed*.8)*400.);float j=cos(elapsed*.5)*.5+.5;i.x=e.x+j*(i.x-e.x);i.y=e.y+j*(i.y-e.y);if(abs(i.x)>resolution.x/.5 || abs(i.y)>resolution.y/.5){fragColor=vec4(1.);return;}int k=int(floor(i.x/b));if(k<0)k=-k;int l=int(floor(i.y/b));if(l<0)l=-l;if(k % 2==l % 2){fragColor=vec4(c,1.);}else{fragColor=vec4(d,1.);;}return;}